queries.04_sanctions_lists:
// The sanctions lists a crypto screening checks against, who publishes them and whether they are imported yet.
// from: - | yields: SanctionsList
MATCH (l:SanctionsList)
OPTIONAL MATCH (l)-[:PUBLISHED_BY]->(g:Regulator)
RETURN l.name AS list, g.short AS publisher, l.refresh AS refresh, l.imported AS imported, l.url AS source
ORDER BY list

queries.05_search_cases:
// Search the cases in full text (title, summary, what happened on chain, party). param: q (e.g. sanctions, registratie, ransomware)
// from: - | yields: Source
MATCH (k:Source {kind: 'case'}) SEARCH k IN (FULLTEXT INDEX crypto_case_text FOR $q LIMIT 10) SCORE AS relevance
RETURN k.party AS party, k.date AS date, k.title AS title, k.url AS source, relevance
ORDER BY relevance DESC
